62	// newCertServer starts a TLS server whose self-signed certificate covers every
63	// name and address the tests use as a target, and returns it with a pool that
64	// trusts it. The certificate is valid for years, so a check reads it as OK.
65	func newCertServer(t *testing.T) (*httptest.Server, *x509.CertPool) {
66		t.Helper()
67		key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
68		if err != nil {
69			t.Fatal(err)
70		}
71		tmpl := &x509.Certificate{
72			SerialNumber:          big.NewInt(581),
73			Subject:               pkix.Name{CommonName: testIssuer},
74			NotBefore:             time.Now().Add(-time.Hour),
75			NotAfter:              time.Now().AddDate(5, 0, 0),
76			KeyUsage:              x509.KeyUsageDigitalSignature | x509.KeyUsageCertSign,
77			ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
78			BasicConstraintsValid: true,
79			IsCA:                  true,
80			DNSNames:              []string{"example.com", "a.corp.test", "localhost"},
81			IPAddresses:           []net.IP{net.ParseIP("127.0.0.1"), net.ParseIP("::1"), net.ParseIP("10.1.2.3")},
82		}
83		der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
84		if err != nil {
85			t.Fatal(err)
86		}
87		srv := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
88			_, _ = io.WriteString(w, "reached")
89		}))
90		srv.Config.ErrorLog = log.New(io.Discard, "", 0) // failed handshakes are on purpose
91		srv.TLS = &tls.Config{Certificates: []tls.Certificate{{Certificate: [][]byte{der}, PrivateKey: key}}}
92		srv.StartTLS()
93		t.Cleanup(srv.Close)
94	
95		pool := x509.NewCertPool()
96		pool.AddCert(srv.Certificate())
97		return srv, pool
98	}
