100	// fixed is a Selector that always answers u.
101	func fixed(u *url.URL) netproxy.Selector {
102		return func(*url.URL) (*url.URL, error) { return u, nil }
103	}
104	
105	// direct is a Selector that never uses a proxy.
106	func direct(*url.URL) (*url.URL, error) { return nil, nil }
107	
108	// useCertDialer swaps certDialer and certRootCAs for the test and restores
109	// them when it ends.
110	func useCertDialer(t *testing.T, d netproxy.Dialer, roots *x509.CertPool) {
111		t.Helper()
112		oldDialer, oldRoots := certDialer, certRootCAs
113		certDialer, certRootCAs = d, roots
114		t.Cleanup(func() { certDialer, certRootCAs = oldDialer, oldRoots })
115	}
116	
117	// routeTo is a Dialer.DialContext that sends the connection for any of names
118	// to addr and leaves other addresses alone.
119	func routeTo(addr string, names ...string) func(context.Context, string, string) (net.Conn, error) {
120		return func(ctx context.Context, network, a string) (net.Conn, error) {
121			for _, n := range names {
122				if a == n {
123					a = addr
124				}
125			}
126			return (&net.Dialer{}).DialContext(ctx, network, a)
127		}
128	}
