141	func leafFingerprint(c *x509.Certificate) string {
142		sum := sha256.Sum256(c.Raw)
143		return hex.EncodeToString(sum[:])
144	}
145	
146	// captureTransport remembers the chain the server presented on each response,
147	// which is what the HTTPS monitor saw.
148	type captureTransport struct {
149		base http.RoundTripper
150	
151		mu     sync.Mutex
152		chains [][]*x509.Certificate
153	}
154	
155	func (c *captureTransport) RoundTrip(req *http.Request) (*http.Response, error) {
156		resp, err := c.base.RoundTrip(req)
157		if resp != nil && resp.TLS != nil {
158			c.mu.Lock()
159			c.chains = append(c.chains, resp.TLS.PeerCertificates)
160			c.mu.Unlock()
161		}
162		return resp, err
163	}
164	
165	func (c *captureTransport) seen() [][]*x509.Certificate {
166		c.mu.Lock()
167		defer c.mu.Unlock()
168		return append([][]*x509.Certificate(nil), c.chains...)
169	}
