182	func TestSSLCheckerThroughProxyMatchesTheHTTPSMonitor(t *testing.T) {
183		srv, pool := newCertServer(t)
184		proxy := connectproxy.Start(t, connectproxy.Options{
185			Route: func(string) string { return srv.Listener.Addr().String() },
186		})
187		sel := fixed(proxy.URL())
188		useCertDialer(t, netproxy.Dialer{Proxy: sel}, pool)
189	
190		// The HTTPS monitor, through the same proxy and the same trust.
191		tr := netproxy.NewTransport(sel)
192		tr.TLSClientConfig = &tls.Config{RootCAs: pool}
193		t.Cleanup(tr.CloseIdleConnections)
194		capture := &captureTransport{base: tr}
195		httpChecker := NewHTTPChecker(5 * time.Second)
196		httpChecker.client.Transport = capture
197	
198		ctx := testContext(t, 20*time.Second)
199		httpRes := httpChecker.Check(ctx, config.ComponentConfig{Name: "web", Type: "https", Target: "example.com"})
200		if httpRes.Status != StatusOK {
201			t.Fatalf("HTTPS monitor = %s (%s), want OK", httpRes.Status, httpRes.Error)
202		}
203		chains := capture.seen()
204		if len(chains) != 1 || len(chains[0]) == 0 {
205			t.Fatalf("the HTTPS monitor saw %d chains, want 1 with a leaf", len(chains))
206		}
207		leaf := chains[0][0]
208	
209		res := NewSSLChecker(5*time.Second).Check(ctx, sslComponent("example.com"))
210		if res.Status != StatusOK {
211			t.Fatalf("SSL monitor = %s (%s), want OK", res.Status, res.Error)
212		}
213		if res.ErrorStage != "" {
214			t.Errorf("ErrorStage = %q on a success, want empty", res.ErrorStage)
215		}
216		if res.SSLExpires == nil || !res.SSLExpires.Equal(leaf.NotAfter) {
217			t.Errorf("SSLExpires = %v, want the HTTPS monitor's %v", res.SSLExpires, leaf.NotAfter)
218		}
219		if res.SSLIssuer != leaf.Issuer.CommonName || res.SSLIssuer != testIssuer {
220			t.Errorf("SSLIssuer = %q, want %q (the HTTPS monitor's %q)", res.SSLIssuer, testIssuer, leaf.Issuer.CommonName)
221		}
222		wantDays := int(time.Until(leaf.NotAfter).Hours() / 24)
223		if res.SSLDaysLeft == nil || *res.SSLDaysLeft < wantDays-1 || *res.SSLDaysLeft > wantDays+1 {
224			t.Errorf("SSLDaysLeft = %v, want about %d", res.SSLDaysLeft, wantDays)
225		}
226	
227		// Both monitors went through the proxy, to the same target.
228		reqs := proxy.Requests()
229		if len(reqs) != 2 {
230			t.Fatalf("proxy received %d CONNECTs, want 2 (one per monitor): %+v", len(reqs), reqs)
231		}
232		for _, r := range reqs {
233			if r.Target != "example.com:443" {
234				t.Errorf("CONNECT target = %q, want example.com:443", r.Target)
235			}
236		}
237	}
