260		tests := []struct {
261			name string
262			code int
263			want string
264		}{
265			{"forbidden", http.StatusForbidden, "proxy: CONNECT refused (403"},
266			{"proxy authentication required", http.StatusProxyAuthRequired, "proxy: CONNECT refused (407"},
267		}
268		for _, tt := range tests {
269			t.Run(tt.name, func(t *testing.T) {
270				_, pool := newCertServer(t)
271				proxy := connectproxy.Start(t, connectproxy.Options{Refuse: tt.code})
