274				res := NewSSLChecker(5*time.Second).Check(testContext(t, 20*time.Second), sslComponent("example.com"))
275				if res.Status != StatusDown {
276					t.Errorf("Status = %s, want %s", res.Status, StatusDown)
277				}
278				if res.ErrorStage != StageProxy {
