291	func TestSSLCheckerCertificateErrorIsNotAProxyStage(t *testing.T) {
292		srv, pool := newCertServer(t)
293		real := srv.Listener.Addr().String()
294		proxy := connectproxy.Start(t, connectproxy.Options{Route: func(string) string { return real }})
295	
296		tests := []struct {
297			name   string
298			dialer netproxy.Dialer
299			roots  *x509.CertPool
300			target string
301		}{
302			// The proxy tunnel works; the certificate is not trusted.
303			{"untrusted through the proxy", netproxy.Dialer{Proxy: fixed(proxy.URL())}, nil, "example.com"},
304			{"untrusted direct", netproxy.Dialer{Proxy: direct, DialContext: routeTo(real, "example.com:443")}, nil, "example.com"},
305			// The root is trusted; the name is not in the certificate: still verified.
306			{"wrong name through the proxy", netproxy.Dialer{Proxy: fixed(proxy.URL())}, pool, "other.test"},
307			{"wrong name direct", netproxy.Dialer{Proxy: direct, DialContext: routeTo(real, "other.test:443")}, pool, "other.test"},
308		}
309		for _, tt := range tests {
310			t.Run(tt.name, func(t *testing.T) {
311				useCertDialer(t, tt.dialer, tt.roots)
312	
313				res := NewSSLChecker(5*time.Second).Check(testContext(t, 20*time.Second), sslComponent(tt.target))
314				if res.Status != StatusDown {
315					t.Errorf("Status = %s, want %s", res.Status, StatusDown)
316				}
317				if res.ErrorStage != "" {
318					t.Errorf("ErrorStage = %q, want empty: the proxy did its job", res.ErrorStage)
319				}
320				if !strings.Contains(res.Error, "x509") {
321					t.Errorf("Error = %q, want an x509 verification error", res.Error)
322				}
323				if strings.HasPrefix(res.Error, "proxy:") {
324					t.Errorf("Error = %q must not read as a proxy failure", res.Error)
325				}
326				if res.SSLExpires != nil || res.SSLIssuer != "" {
327					t.Errorf("an unverified chain must not fill the SSL fields: %v %q", res.SSLExpires, res.SSLIssuer)
328				}
329			})
330		}
