339			ctx     func(t *testing.T) context.Context
340			timeout time.Duration
341		}{
342			{"timeout argument", func(t *testing.T) context.Context { return testContext(t, time.Minute) }, 300 * time.Millisecond},
343			{"context deadline", func(t *testing.T) context.Context { return testContext(t, 300*time.Millisecond) }, time.Minute},
344			{"context cancelled", func(t *testing.T) context.Context {
345				ctx, cancel := context.WithCancel(context.Background())
346				time.AfterFunc(300*time.Millisecond, cancel)
347				t.Cleanup(cancel)
348				return ctx
349			}, time.Minute},
350		}
351		for _, tt := range tests {
352			t.Run(tt.name, func(t *testing.T) {
353				start := time.Now()
354				chain, err := FetchCertificateChainContext(tt.ctx(t), "example.com:443", tt.timeout)
355				if elapsed := time.Since(start); elapsed > 3*time.Second {
356					t.Errorf("returned after %v, want about 300ms", elapsed)
357				}
358				if err == nil || len(chain) != 0 {
359					t.Fatalf("got %d certificates and err %v, want an error", len(chain), err)
360				}
361				var pe *netproxy.Error
362				if !errors.As(err, &pe) {
363					t.Fatalf("error = %T %v, want a *netproxy.Error", err, err)
