491	// TestSSLFetchChainFollowsTheProxyEnvironment runs the SSL monitor's fetch in a
492	// child process with real HTTPS_PROXY and NO_PROXY values, as a user would set
493	// them: a target that is not excluded travels through the proxy (one CONNECT),
494	// an excluded one is dialed directly (no CONNECT) and yields the same chain.
495	func TestSSLFetchChainFollowsTheProxyEnvironment(t *testing.T) {
496		srv, _ := newCertServer(t)
497		real := srv.Listener.Addr().String()
498		_, realPort, err := net.SplitHostPort(real)
499		if err != nil {
500			t.Fatal(err)
501		}
502		proxy := connectproxy.Start(t, connectproxy.Options{Route: func(string) string { return real }})
503		proxyHost := proxy.URL().Host
504		wantChain := leafFingerprint(srv.Certificate())
505		httpsProxy := map[string]string{"HTTPS_PROXY": proxy.URL().String()}
506		withNoProxy := func(v string) map[string]string {
507			return map[string]string{"HTTPS_PROXY": proxy.URL().String(), "NO_PROXY": v}
508		}
509	
510		tests := []struct {
511			name         string
512			target       string
513			vars         map[string]string
514			wantDialed   string // the address the child's DialContext was asked for
515			wantConnects int
516		}{
517			{"not excluded goes through the proxy", "a.corp.test:443", httpsProxy, proxyHost, 1},
518			{"NO_PROXY on another host does not exclude", "a.corp.test:443", withNoProxy("b.corp.test"), proxyHost, 1},
519			{"no proxy variable is direct", "a.corp.test:443", nil, real, 0},
520			{"NO_PROXY exact name", "a.corp.test:443", withNoProxy("a.corp.test"), real, 0},
521			{"NO_PROXY domain suffix", "a.corp.test:443", withNoProxy("corp.test"), real, 0},
522			{"NO_PROXY dotted suffix", "a.corp.test:443", withNoProxy(".corp.test"), real, 0},
523			{"NO_PROXY CIDR", "10.1.2.3:443", withNoProxy("10.0.0.0/8"), real, 0},
524			// Go never proxies localhost nor a loopback address, whatever NO_PROXY says.
525			{"localhost is never proxied", "localhost:" + realPort, httpsProxy, real, 0},
526			{"loopback address is never proxied", "127.0.0.1:" + realPort, httpsProxy, real, 0},
527		}
528		for _, tt := range tests {
529			t.Run(tt.name, func(t *testing.T) {
530				extra := map[string]string{
531					envHelper: "1",
532					envTarget: tt.target,
533					envServer: real,
534					envCert:   base64.StdEncoding.EncodeToString(srv.Certificate().Raw),
535				}
536				before := len(proxy.Requests())
537				got := runChild(t, extra, tt.vars)
538				if want := "chain " + wantChain + " dialed " + tt.wantDialed; got != want {
539					t.Fatalf("child with %v = %q, want %q", tt.vars, got, want)
540				}
541				reqs := proxy.Requests()[before:]
