36	// DEVDESK-581: the SSL monitor opens its own TLS connection, so it must follow
37	// the same proxy path as the HTTPS monitor. These tests drive the package
38	// variables certDialer and certRootCAs; none of them runs in parallel.
39	//
40	// Everything that targets "example.com:443" is redirected by the proxy (or by
41	// an injected DialContext) to a local test server; nothing reaches the network.
42	
43	const (
44		// testIssuer is the CommonName of the generated certificate (self-signed,
45		// so also its issuer).
46		testIssuer = "DevDesk Test"
47	
48		// envHelper makes the test binary run TestSSLEnvironmentHelper for real.
49		envHelper = "STATUS_TEST_SSL_HELPER"
50		// envTarget is the target the helper fetches a chain from.
51		envTarget = "STATUS_TEST_SSL_TARGET"
52		// envServer is the address the helper's DialContext gives the target when
53		// it is dialed directly.
54		envServer = "STATUS_TEST_SSL_SERVER"
55		// envCert is the server certificate, DER in base64: the helper's roots.
