117	// routeTo is a Dialer.DialContext that sends the connection for any of names
118	// to addr and leaves other addresses alone.
119	func routeTo(addr string, names ...string) func(context.Context, string, string) (net.Conn, error) {
120		return func(ctx context.Context, network, a string) (net.Conn, error) {
121			for _, n := range names {
122				if a == n {
123					a = addr
124				}
125			}
126			return (&net.Dialer{}).DialContext(ctx, network, a)
127		}
128	}
