389	// TestSSLEnvironmentHelper is the child half of
390	// TestSSLFetchChainFollowsTheProxyEnvironment: it does nothing in a normal run.
391	// http.ProxyFromEnvironment reads the proxy variables once per process, so
392	// t.Setenv cannot steer it: the parent runs the test binary again with the
393	// variables it wants. The child keeps the zero Dialer's proxy choice (the
394	// environment) and only redirects the direct dial of the target to the test
395	// server; it prints which addresses it dialed and which chain it obtained.
396	func TestSSLEnvironmentHelper(t *testing.T) {
397		if os.Getenv(envHelper) != "1" {
398			t.Skip("child of TestSSLFetchChainFollowsTheProxyEnvironment")
399		}
400		der, err := base64.StdEncoding.DecodeString(os.Getenv(envCert))
401		if err != nil {
402			t.Fatal(err)
403		}
404		cert, err := x509.ParseCertificate(der)
405		if err != nil {
406			t.Fatal(err)
407		}
408		pool := x509.NewCertPool()
409		pool.AddCert(cert)
410	
411		var (
412			mu     sync.Mutex
413			dialed []string
414		)
415		target := os.Getenv(envTarget)
416		server := os.Getenv(envServer)
417		useCertDialer(t, netproxy.Dialer{DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
418			if addr == target {
419				addr = server
420			}
421			mu.Lock()
422			dialed = append(dialed, addr)
423			mu.Unlock()
424			return (&net.Dialer{}).DialContext(ctx, network, addr)
425		}}, pool)
426	
427		chain, err := FetchCertificateChainContext(testContext(t, 10*time.Second), target, 5*time.Second)
428		mu.Lock()
429		defer mu.Unlock()
430		if err != nil {
431			fmt.Println(resultPrefix + "error: " + err.Error())
432			return
433		}
434		if len(chain) == 0 {
435			fmt.Println(resultPrefix + "error: empty chain")
436			return
437		}
438		fmt.Printf("%schain %s dialed %s\n", resultPrefix, leafFingerprint(chain[0]), strings.Join(dialed, ","))
439	}
440	
441	// childEnvVars are removed from the parent's environment before the child
442	// starts, so a developer's own proxy settings never leak into a case.
443	var childEnvVars = []string{
444		"HTTPS_PROXY", "https_proxy", "HTTP_PROXY", "http_proxy",
445		"NO_PROXY", "no_proxy", "REQUEST_METHOD",
446		envHelper, envTarget, envServer, envCert,
447	}
